
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_th4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_th4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.469835000278503e+00, -4.378697418165939e+00, -4.251552351828231e+00, -4.076556037133884e+00, -3.840356115888981e+00, -3.530407816148674e+00, -3.139902051849754e+00, -2.675932522150720e+00, -2.168574914128896e+00, -1.664196170103683e+00, -1.144577433323031e+00, -7.489747094128922e-01, -6.511050538368007e-01, -5.354469582556401e-01, -3.880721108688840e-01, -2.446272731574638e-01, -1.243338941687916e-01, -2.940860117951984e-02, 3.259781870841821e-02, 6.145509173969965e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


